package com.example.uploads;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;

/** Stores uploaded files in an upload directory. */
public final class Uploads {
    private Uploads() {
    }

    public static Path save(Path dir, String filename, String data) throws IOException {
        Path file = dir.resolve(filename);
        Files.write(file, data.getBytes(StandardCharsets.UTF_8));
        return file;
    }
}

package com.example.uploads;

import static org.junit.jupiter.api.Assertions.assertTrue;

import java.nio.file.Files;
import java.nio.file.Path;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class UploadsTest {
    @TempDir
    Path dir;

    @Test
    void savesFile() throws Exception {
        Uploads.save(dir, "a.txt", "x");
        assertTrue(Files.exists(dir.resolve("a.txt")));
    }
}
